#pragma once

#include <cstdint>
#include <string>

// YKTK3 skills for the cheat tabs: every ID of the game's own skill name tables with a Korean name (player_skills.inc,
// generated by tools/gen_skill_table.py). The Japanese name is read from the same tables in guest RAM (the game's ELF data)
// when a tab asks for it, so no game text is kept in the source.
namespace urban::skills
{
    enum Group : int
    {
        kPlayer = 0,      // 0x01-0x6B without the WS ones
        kWinningShot = 1, // WS (winning shot) pitches
        kManager = 2,     // 0xC9-0xE1
        kCoach = 3,       // 0x12D-0x145
        kScout = 4,       // 1-43, an ID space of their own (scout records only)
        kGroups = 5
    };

    struct Skill
    {
        uint16_t id;
        int group;
        const char *ko;
    };

    const Skill *begin();
    const Skill *end();
    // A known skill: scout skills in their own space, the others (player, WS, manager, coach) in the shared one.
    const Skill *find(uint16_t id, bool scout);
    const char *groupName(int group);
    // "한국어  日本語" (the Japanese part once the game's tables are in RAM; half-width kana made full-width for the font).
    std::string label(const uint8_t *rdram, const Skill &skill);
}
